() => {
  const setVal = (el, val) => {
    const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
    setter.call(el, val);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  const inputs = Array.from(document.querySelectorAll('input'));
  const user = inputs.find(i => i.placeholder && i.placeholder.includes('用户名'));
  const pass = inputs.find(i => i.type === 'password' || (i.placeholder && i.placeholder.includes('密码')));
  if (!user || !pass) return {user: !!user, pass: !!pass};
  setVal(user, 'analyst1');
  setVal(pass, 'analyst123');
  return {user: user.value, pass: pass.value};
}

