async () => {
  const start = Date.now();
  const maxMs = 195000;
  const check = () => {
    const btns = Array.from(document.querySelectorAll('button'));
    const genBtn = btns.find(b => b.textContent.includes('生成决策报表') || b.textContent.includes('正在计算'));
    const btnText = genBtn ? genBtn.textContent.trim() : null;
    const btnDisabled = genBtn ? genBtn.disabled : null;
    // look for error banners: red text or elements with role=alert
    const allText = Array.from(document.querySelectorAll('div, p, span')).map(el => el.textContent.trim()).filter(t => t && t.length < 500);
    const errorText = allText.find(t => t.includes('Cannot read properties') || t.includes('replace') || t.includes('生成失败') || t.includes('错误'));
    const alerts = Array.from(document.querySelectorAll('[role="alert"], .error, [class*="error"]')).map(el => el.textContent.trim()).filter(t => t);
    // count history reports
    const histMatch = document.body.innerText.match(/已生成的历史报表列表\s*\((\d+)\)/);
    return {btnText, btnDisabled, errorText, alerts, histCount: histMatch ? histMatch[1] : null, elapsed: Math.round((Date.now()-start)/1000)};
  };
  while (Date.now() - start < maxMs) {
    const s = check();
    if (s.errorText || s.alerts.length > 0) return {done: true, reason: 'error-detected', ...s};
    if (s.btnText && s.btnText.includes('立即生成决策报表') && s.btnDisabled === false) {
      // generation finished (button re-enabled)
      return {done: true, reason: 'button-reenabled', ...s};
    }
    await new Promise(r => setTimeout(r, 5000));
  }
  return {done: false, reason: 'timeout', ...check()};
}

