() => {
  const bodyText = document.body.innerText;
  const histMatch = bodyText.match(/已生成的历史报表列表\s*\((\d+)\)/);
  // Find report headings (h2)
  const h2s = Array.from(document.querySelectorAll('h2')).map(h => h.textContent.trim());
  const h3s = Array.from(document.querySelectorAll('h3')).map(h => h.textContent.trim());
  const h4s = Array.from(document.querySelectorAll('h4')).map(h => h.textContent.trim()).slice(0, 10);
  // check for any red error banners
  const redEls = Array.from(document.querySelectorAll('*')).filter(el => {
    if (el.children.length > 0) return false;
    const style = getComputedStyle(el);
    const cls = el.className.toString();
    return (cls.includes('red') || cls.includes('error') || cls.includes('destructive')) && el.textContent.trim().length > 3;
  }).map(el => el.textContent.trim().slice(0, 200));
  // KPI cards
  const kpiIdx = bodyText.indexOf('核心绩效KPI');
  const insightIdx = bodyText.indexOf('核心洞察');
  const chartIdx = bodyText.indexOf('可视化报表图表');
  const summaryIdx = bodyText.indexOf('高管摘要');
  return {histCount: histMatch ? histMatch[1] : null, h2s, h3s, h4s, redEls, hasKPI: kpiIdx>=0, hasInsights: insightIdx>=0, hasCharts: chartIdx>=0, hasSummary: summaryIdx>=0};
}

