() => {
  // Find inner scroll containers and expand them so fullPage screenshot captures everything
  const all = Array.from(document.querySelectorAll('*'));
  const scrolled = all.filter(el => el.scrollHeight > el.clientHeight + 50 && el.clientHeight > 200);
  const info = scrolled.map(el => ({tag: el.tagName, cls: el.className.toString().slice(0,60), sh: el.scrollHeight, ch: el.clientHeight}));
  scrolled.forEach(el => {
    el.style.overflow = 'visible';
    el.style.height = 'auto';
    el.style.maxHeight = 'none';
  });
  document.body.style.overflow = 'visible';
  document.documentElement.style.overflow = 'visible';
  window.scrollTo(0, 0);
  return info;
}

